Closes #{ISSUE_ID}

Asistido-por-IA: {MODELO_IA}
"@
gh pr create --base dev --title "{RESUMEN}" --body $cuerpo

cs.manualCmdTpl:
# PowerShell 5.1 o 7. Cierra el milestone del sprint si no le quedan issues abiertos, y muestra el tablero
function Assert-Gh { if ($LASTEXITCODE -ne 0) { throw "gh fallo con codigo $LASTEXITCODE" } }
$Hitos = gh api 'repos/{GH_OWNER}/{GH_REPO}/milestones?state=open' | ConvertFrom-Json; Assert-Gh
$M = $Hitos | Where-Object { $_.title -eq '{SPRINT}' }
if (-not $M) { throw "no hay milestone abierto con titulo '{SPRINT}'" }
"{SPRINT}: abiertos=$($M.open_issues) cerrados=$($M.closed_issues)"
if ($M.open_issues -eq 0) {
  gh api -X PATCH "repos/{GH_OWNER}/{GH_REPO}/milestones/$($M.number)" -f state=closed | Out-Null; Assert-Gh
  "milestone '{SPRINT}' cerrado"
} else {
  "quedan issues abiertos: muevelos al proximo sprint (gh issue edit <n> --milestone '<siguiente>') y vuelve a correr"
}

# Tablero del Project: todo lo del sprint deberia estar en Done
$N = ((gh project list --owner {GH_OWNER} --format json | ConvertFrom-Json).projects | Where-Object { $_.title -eq '{GH_REPO}' }).number; Assert-Gh
(gh project item-list $N --owner {GH_OWNER} --format json | ConvertFrom-Json).items | ForEach-Object { '#' + $_.content.number + ' ' + $_.status }
